describe('Order Summary Before Payment Confirmation', () => {
  beforeEach(() => {
    cy.visit('/cart');
  });

  it('should display order summary before confirming payment', () => {
    // Add items to cart
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="product-1"]').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="product-2"]').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();

    // Navigate to checkout
    cy.get('[data-testid="checkout-btn"]').click();

    // Verify order summary is visible
    cy.get('[data-testid="order-summary-section"]').should('be.visible');
    cy.get('[data-testid="subtotal"]').should('contain', '$100.00');
    cy.get('[data-testid="shipping-cost"]').should('contain', '$5.00');
    cy.get('[data-testid="tax-amount"]').should('contain', '$8.50');
    cy.get('[data-testid="total-amount"]').should('contain', '$113.50');

    // Verify order items are listed
    cy.get('[data-testid="order-item-list"]').should('be.visible');
    cy.get('[data-testid="order-item-row"]').should('have.length', 2);

    // Verify confirmation button is visible
    cy.get('[data-testid="confirm-payment-btn"]').should('be.visible');
    cy.get('[data-testid="confirm-payment-btn"]').should('not.be.disabled');

    // Click confirm payment
    cy.get('[data-testid="confirm-payment-btn"]').click();
    cy.get('[data-testid="payment-processing-spinner"]').should('be.visible');
    cy.get('[data-testid="payment-success-message"]').should('be.visible');
  });

  it('should handle empty cart and prevent order summary display', () => {
    // Verify cart is empty
    cy.get('[data-testid="cart-items-container"]').should('not.exist');
    cy.get('[data-testid="empty-cart-message"]').should('be.visible');
    cy.get('[data-testid="empty-cart-message"]').should('contain', 'Your cart is empty');

    // Verify order summary is not displayed
    cy.get('[data-testid="order-summary-section"]').should('not.exist');

    // Verify checkout button is disabled or hidden
    cy.get('[data-testid="checkout-btn"]').should('be.disabled');

    // Attempt to click disabled button
    cy.get('[data-testid="checkout-btn"]').click({ force: true });

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please add items to your cart');
  });
});
